// Repeated controls share their labels; each rendered scope has its own anchor.
export const NOTIFICATION_FIELD_LABELS = {
  enabled: 'Enabled', system: 'System', browser: 'Browser', qqReport: 'QQ Report', qqSubscribe: 'QQ Subscribe',
} as const;
export const AUTO_REPORT_SOURCE_LABELS = { system: 'System', ma: 'MA', user: 'Real user' } as const;
export const SETTING_PERMISSIONS = {
  trigger: ['read', 'create', 'updateConfig', 'lifecycle', 'delete'],
  action: ['read', 'create', 'updateConfig', 'lifecycle', 'delete', 'manageSystemActions'],
  jobTemplate: ['read', 'create', 'updateConfig', 'use', 'delete'],
  job: ['read', 'create', 'updateConfig', 'lifecycle', 'execute', 'delete'],
} as const;
export const SETTING_DESCRIPTIONS: readonly SettingDescription[] = [
  ...BASE_DESCRIPTIONS,
  {"id":"settings-search-nav","tab":"appearance","label":"Search","searchable":false},
  {"id":"settings-search-panel","tab":"appearance","label":"Search settings panel","searchable":false},
  {"id":"settings-search-heading","tab":"appearance","label":"Search settings","searchable":false},
  {"id":"settings-search-reset","tab":"appearance","label":"Reset","searchable":false},

  ...BASE_DESCRIPTIONS.filter(item => item.id.startsWith('error-notification-exclusions.')).map(item => ({...item, id: 'behavior.' + item.id, anchor: 'behavior.' + (item.anchor ?? item.id), tab: 'behavior' as const})),
  ...Object.entries(SETTING_PERMISSIONS).flatMap(([kind, caps]) => caps.map(cap => ({
    id: `agent-permissions.${kind}.${cap}`, tab: 'authorization' as const, label: `${kind}.${cap}`,
    hint: 'Agent permissions', gate: 'authorized' as const, anchor: `agent-permissions.${kind}.${cap}`,
  }))),
  ...(['locker-new-unread', 'new-errors', 'completion-bell'] as const).flatMap((scope) =>
    Object.entries(NOTIFICATION_FIELD_LABELS)
      .filter(([key]) => scope === 'completion-bell' ? key !== 'enabled' : key !== 'qqSubscribe')
      .map(([key, label]) => ({ id: scope + '.' + key, tab: 'notifications' as const, label,
        hint: BASE_DESCRIPTIONS.find((item) => item.id === scope)!.label, anchor: scope + '.' + key }))),
  ...(['auto-report', 'prompt-summary'] as const).flatMap((scope) =>
    Object.entries(AUTO_REPORT_SOURCE_LABELS).map(([key, label]) => ({
      id: scope + '.' + key, tab: 'behavior' as const, label,
      hint: BASE_DESCRIPTIONS.find((item) => item.id === scope)!.label, anchor: scope + '.' + key,
    }))),
];
